def solve(grid):
    # Find the two separator columns (all rows are 0)
    rows = len(grid)
    cols = len(grid[0])
    sep = []
    for c in range(cols):
        if all(grid[r][c] == 0 for r in range(rows)):
            sep.append(c)
            if len(sep) == 2:
                break

    # Define the three regions between the separators
    regions = [
        (0, sep[0] - 1),
        (sep[0] + 1, sep[1] - 1),
        (sep[1] + 1, cols - 1)
    ]

    # Helper to identify the pattern of zeros inside a region
    def code_for_region(start_col, end_col):
        zeros = set()
        for r in range(rows):
            for c in range(start_col, end_col + 1):
                if grid[r][c] == 0:
                    # store local coordinates (row, column)
                    zeros.add((r, c - start_col))

        if not zeros:
            return 2                     # empty region
        if len(zeros) == 4:
            # Normalized positions (local to the 4x4 region)
            # Possible 2x2 blocks
            central_mid   = {(1,1),(1,2),(2,1),(2,2)}   # middle rows, middle cols
            central_bottom= {(2,1),(2,2),(3,1),(3,2)}   # bottom rows, middle cols
            corners       = {(1,0),(1,3),(2,0),(2,3)}   # left/right corners in middle rows

            if zeros == central_mid:
                return 8
            if zeros == central_bottom:
                return 4
            if zeros == corners:
                return 3
        # Default fallback (should not occur for valid inputs)
        return 2

    # Compute a code for each region
    codes = [code_for_region(s, e) for (s, e) in regions]

    # Build the 3×3 output grid (each row repeats its code three times)
    out_grid = [[codes[i]] * 3 for i in range(3)]
    return out_grid

